// Bitrix giden webhook gövdesini çözer (urlencoded: iç içe ya da düz anahtar gelebilir)
const ayar = $('Ayarlar').first().json;
const b = $input.first().json.body || {};
const event = String(b.event || '').toUpperCase();
const id = (b.data && b.data.FIELDS && b.data.FIELDS.ID) || b['data[FIELDS][ID]'];
const token = (b.auth && b.auth.application_token) || b['auth[application_token]'];

const TIPLER = { ONCRMLEADADD: { ownerTypeId: 1, yol: 'lead' }, ONCRMDEALADD: { ownerTypeId: 2, yol: 'deal' } };
const tip = TIPLER[event];
if (!tip || !id) return [];
if (ayar.bitrixAppToken && ayar.bitrixAppToken !== 'BURAYA_GIDEN_WEBHOOK_TOKEN' && token !== ayar.bitrixAppToken) {
  throw new Error('Geçersiz Bitrix application_token');
}
return [{ json: { ownerId: String(id), ...tip, bitrixUrl: ayar.bitrixWebhookUrl.replace(/\/?$/, '/') } }];

// DAGITIM = 'sira' -> hangi form doldurulursa doldurulsun 10 gruba sırayla dağıtır (aktif: false olan atlanır)
// DAGITIM = 'form' -> her başvuru doldurulan formun kendi grubuna gider
const DAGITIM = 'sira';

// Form adı -> Telegram grubu. Form adı, CRM_WEBFORM aktivitesinin konusundan okunur:
// "19 TİMUÇİN FORM" başlıklı CRM formu gönderildi
const FORMS = [
  { no: 10, ad: 'MELTEM EFAS FORM',         anahtar: 'MELTEM',        chatId: '-5106515364', kisi: 'Meltem',        aktif: true },
  { no: 11, ad: 'BURCU EFAS FORM',          anahtar: 'BURCU',         chatId: '-5454384941', kisi: 'Burcu', aktif: true },
  { no: 12, ad: 'CAFER EFAS FORM',          anahtar: 'CAFER',         chatId: '-5440932746', kisi: 'Cafer', aktif: true },
  { no: 13, ad: 'MUSTAFA UTKU EFAS FORM',   anahtar: 'MUSTAFA UTKU',  chatId: '-5451627345', kisi: 'Mustafa Utku', aktif: true },
  { no: 14, ad: 'MUSTAFA ALTAY EFAS FORM',  anahtar: 'MUSTAFA ALTAY', chatId: '-5250586334', kisi: 'Mustafa Altay', aktif: true },
  { no: 15, ad: 'MURAT ER EFAS FORM',       anahtar: 'MURAT ER',      chatId: '-5483964717', kisi: 'Murat Er', aktif: true },
  { no: 16, ad: 'BERKCAN KARTAL EFAS FORM', anahtar: 'BERKCAN',       chatId: '-5297361374', kisi: 'Berkcan Kartal', aktif: true },
  { no: 17, ad: 'FATIH EFAS FORM',          anahtar: 'FATIH',         chatId: '-5104387991', kisi: 'Fatih', aktif: true },
  { no: 18, ad: 'DEMET EFAS FORM',          anahtar: 'DEMET',         chatId: '-5300073899', kisi: 'Demet', aktif: true },
  { no: 19, ad: 'TIMUCIN FORM',             anahtar: 'TIMUCIN',       chatId: '-1004383902607', kisi: 'Timuçin', aktif: true },
];

const norm = s => String(s || '').toLocaleUpperCase('tr-TR')
  .replace(/İ/g, 'I').replace(/Ş/g, 'S').replace(/Ğ/g, 'G')
  .replace(/Ü/g, 'U').replace(/Ö/g, 'O').replace(/Ç/g, 'C').replace(/\s+/g, ' ').trim();
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const olay = $('Olayı Çöz').first().json;
const acts = $('Form Aktivitesi Getir').first().json.result || [];

let form = null, act = null, formAdi = '';
for (const a of acts) {
  const m = String(a.SUBJECT || '').match(/"([^"]+)"/);
  if (!m) continue;
  const ad = norm(m[1]);
  // Ad "<no> <anahtar> ..." ile başlamalı (örn. "19 TIMUCIN FORM"); başka formlarla karışmasın
  const f = FORMS.find(f => ad === `${f.no} ${f.ad}` || ad.startsWith(`${f.no} ${f.anahtar} `) || ad === `${f.no} ${f.anahtar}`);
  if (f) { form = f; act = a; formAdi = m[1]; break; }
}
if (!form) return []; // bu 10 formdan biri değil -> sessizce dur

// Hedef grubu seç
let hedef = form;
let siraNo = null;
if (DAGITIM === 'sira') {
  const aktifler = FORMS.filter(f => f.aktif);
  if (!aktifler.length) throw new Error('Aktif kişi yok');
  const st = $getWorkflowStaticData('global'); // sadece Publish edilmiş (production) çalışmalarda kalıcı
  const son = FORMS.findIndex(f => f.no === st.sonNo);
  // listede son atanandan sonraki ilk aktif kişi
  hedef = aktifler[0];
  for (let i = 1; i <= FORMS.length; i++) {
    const f = FORMS[(son + i + FORMS.length) % FORMS.length];
    if (f.aktif) { hedef = f; break; }
  }
  st.sonNo = hedef.no;
  st.toplam = (st.toplam || 0) + 1;
  siraNo = st.toplam;
}

const alanlar = {};
for (const fld of (act.PROVIDER_PARAMS && act.PROVIDER_PARAMS.FIELDS) || []) {
  alanlar[fld.type === 'phone' ? 'tel' : fld.type === 'email' ? 'mail' : fld.code] = (fld.value || []).join(', ');
}
const ad = alanlar.LEAD_TITLE || alanlar.CONTACT_NAME || alanlar.LEAD_NAME || '-';
const not = (alanlar.LEAD_COMMENTS || alanlar.CONTACT_COMMENTS || '').replace(/_+/g, ' ').trim();
const portal = $('Ayarlar').first().json.bitrixPortalUrl.replace(/\/$/, '');
const tarih = new Date(act.CREATED || Date.now()).toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul' });

const satirlar = [
  '🔔 <b>Yeni Form Başvurusu</b>',
  '',
  `👨‍💼 <b>Atanan:</b> ${esc(hedef.kisi)}`,
  `📋 <b>Doldurulan form:</b> ${esc(formAdi)}`,
  `👤 <b>Ad Soyad:</b> ${esc(ad)}`,
  `📞 <b>Telefon:</b> ${esc(alanlar.tel || '-')}`,
];
if (alanlar.mail) satirlar.push(`✉️ <b>E-posta:</b> ${esc(alanlar.mail)}`);
if (not) satirlar.push(`📝 <b>Cevap:</b> ${esc(not)}`);
satirlar.push(`🕒 <b>Tarih:</b> ${esc(tarih)}`);
satirlar.push(`🔗 <a href="${portal}/crm/${olay.yol}/details/${olay.ownerId}/">Bitrix'te aç (#${olay.ownerId})</a>`);

return [{ json: { chatId: hedef.chatId, atanan: hedef.kisi, form: formAdi, siraNo, text: satirlar.join('\n') } }];
